  // ── Défis : progression ───────────────────────────────────────────────────

  Future<List<DefiProgres>> getDefisProgres(String periode) async {
    final db = await database;
    final rows = await db.query(
      'defis_progres',
      where: 'periode = ?',
      whereArgs: [periode],
    );
    return rows.map((r) => DefiProgres.fromMap(r)).toList();
  }

  Future<void> upsertDefiProgres(
    String defiId,
    String periode,
    int delta,
    int cible,
  ) async {
    final db = await database;
    final rows = await db.query(
      'defis_progres',
      where: 'defi_id = ? AND periode = ?',
      whereArgs: [defiId, periode],
    );
    if (rows.isEmpty) {
      final progres = delta.clamp(0, cible);
      await db.insert('defis_progres', {
        'defi_id': defiId,
        'periode': periode,
        'progres': progres,
        'complete': progres >= cible ? 1 : 0,
      });
    } else {
      final current = rows.first['progres'] as int;
      final newProgres = (current + delta).clamp(0, cible);
      await db.update(
        'defis_progres',
        {'progres': newProgres, 'complete': newProgres >= cible ? 1 : 0},
        where: 'defi_id = ? AND periode = ?',
        whereArgs: [defiId, periode],
      );
    }
  }

  // ── Réalisations : progression ────────────────────────────────────────────

  Future<List<RealisationProgres>> getAllRealisationsProgres() async {
    final db = await database;
    final rows = await db.query('realisations_progres');
    return rows.map((r) => RealisationProgres.fromMap(r)).toList();
  }

  Future<void> upsertRealisationProgres(
    String realId,
    int delta,
    int cible,
  ) async {
    final db = await database;
    final rows = await db.query(
      'realisations_progres',
      where: 'realisation_id = ?',
      whereArgs: [realId],
    );
    if (rows.isEmpty) {
      final progres = delta.clamp(0, cible);
      final debloque = progres >= cible;
      await db.insert('realisations_progres', {
        'realisation_id': realId,
        'progres': progres,
        'debloquee': debloque ? 1 : 0,
        'debloque_le': debloque ? DateTime.now().toIso8601String() : null,
      });
    } else {
      final current = rows.first;
      if ((current['debloquee'] as int) == 1) return; // déjà débloquée
      final newProgres = ((current['progres'] as int) + delta).clamp(0, cible);
      final debloque = newProgres >= cible;
      await db.update(
        'realisations_progres',
        {
          'progres': newProgres,
          'debloquee': debloque ? 1 : 0,
          'debloque_le': debloque ? DateTime.now().toIso8601String() : null,
        },
        where: 'realisation_id = ?',
        whereArgs: [realId],
      );
    }
  }

  Future<void> _ensurePrefsRow(Database db) async {
    final rows = await db.query('user_preferences', where: 'id = 1');
    if (rows.isEmpty) {
      await db.insert('user_preferences', {
        'id': 1,
        'zone': '',
        'niveau_scolaire': 'Fondamental',
        'annee': '7e AF',
        'pays': 'Haïti',
        'ville': '',
        'difficulte': 'Toutes',
        'profil_configure': 0,
      });
    }
  }

  Future<void> _seedData(Database db) async {
    Future<void> ajouterMatiere(
      String niveau,
      String nomMatiere,
      List<_ChapitreSeed> chapitres,
    ) async {
      final matiereId = await db.insert('matieres', {
        'niveau': niveau,
        'nom': nomMatiere,
      });
      for (final chapitre in chapitres) {
        final chapitreId = await db.insert('chapitres', {
          'matiere_id': matiereId,
          'titre': chapitre.titre,
        });
        for (final carte in chapitre.cartes) {
          await db.insert('cartes_mentales', {
            'chapitre_id': chapitreId,
            'contenu': carte,
            'image': null,
          });
        }
        for (final q in chapitre.questions) {
          await db.insert('questions', {
            'chapitre_id': chapitreId,
            'enonce': q.enonce,
            'choix': jsonEncode(q.choix),
            'bonne_reponse': q.bonneReponse,
            'explication': q.explication,
            'niveau_complexite': q.niveauComplexite,
          });
        }
      }
    }

    // ══════════════════════════════════════════
    // MATIÈRES COMMUNES (Fondamental + Secondaire)
    // ══════════════════════════════════════════

    await ajouterMatiere('Commun', 'Communication Créole', [
      _ChapitreSeed(
          titre: 'Orthographe et phonologie du créole haïtien',
          cartes: [
          'Le créole haïtien a une orthographe phonémique officielle depuis 1979 : chaque son est représenté par un seul caractère.',
          'Les voyelles nasales en créole s\'écrivent avec un "n" après la voyelle : an, en, on, in.',
          'Le créole haïtien ne possède pas d\'accent écrit. L\'accent tonique tombe généralement sur la dernière syllabe.',
          'Les sons "ch" et "j" du français correspondent à "ch" et "j" en créole : "chache" (chercher), "jwèt" (jouet).',
          'Le "h" n\'est jamais muet en créole haïtien : "hat" se prononce comme en anglais.',
          ],
          questions: [
          _QSeed(
              'En quelle année l\'orthographe officielle du créole haïtien fut-elle établie ?',
              ['En 1979', 'En 1804', 'En 1961', 'En 2000'],
              'En 1979',
              'Avant 1979, plusieurs orthographes coexistaient. L\'orthographe de 1979 (McConnell-Laubach-Pressoir révisée) est phonémique et systématique. Elle a été fixée par décret, puis confortée par la Constitution de 1987.',
              'Moyen',
            ),
          _QSeed(
              'Que signifie le mot créole « manje » ?',
              ['Manger ou nourriture', 'Maison ou foyer', 'Enfant ou bébé', 'Partir ou sortir'],
              'Manger ou nourriture',
              '"Mwen manje manje" = "Je mange de la nourriture." Le même mot peut être verbe ou nom en créole selon sa position. Le sens (verbe ou nom) dépend du contexte.',
              'Facile',
            ),
          _QSeed(
              'Comment écrit-on "école" en créole haïtien ?',
